/** Every catalog ID a piece answers to: its own, and its variants'. */
export function refsOf(s: LibrarySection): string[] {
  const own = (r: { ref: string; variants?: Array<{ ref: string }> }) => [r.ref, ...(r.variants ?? []).map((v) => v.ref)];
  return s.ref ? [...own({ ref: s.ref, variants: s.variants }), ...(s.also ?? []).flatMap(own)] : [];
}

/** A component's versions: the entries that say they are a version of its catalog ID (c.pagination -> c.pagination@classic…). */
export function versionsOf(ref: string, pool: LibrarySection[] = [...LIBRARY_SECTIONS, ...PROPOSED_SECTIONS]): LibrarySection[] {
  return pool.filter((s) => s.versionOf === ref);
}

/** The pieces that use a catalog ID (or any of a component's variants), from their "uses" lists. */
export function usedBy(ref: string, pool: LibrarySection[] = [...LIBRARY_SECTIONS, ...PROPOSED_SECTIONS]): LibrarySection[] {
  return pool.filter((s) => (s.uses ?? []).some((u) => u === ref || u.startsWith(`${ref}.`)));
}

/**
 * The one line an agent reads for a piece instead of its file: ID, what it is, how to use it, what it's built from and
 * which tokens style it. Assembling a layout from these lines means reading a few hundred characters per part, not a
 * few hundred lines.
 */
export function assemblyLine(s: LibrarySection): string {
  const parts = [`${s.ref ?? s.id}: ${s.name}.`];
  if (s.variants?.length) parts.push(`Variants: ${s.variants.map((v) => `${v.ref} (${v.look})`).join("; ")}.`);
  if (s.usage) parts.push(`Use: ${s.usage}`);
  if (s.uses?.length) parts.push(`Built from: ${s.uses.join(", ")}.`);
  if (s.tokens?.length) parts.push(`Styled by tokens: ${s.tokens.join(" ")}.`);
  for (const a of s.also ?? []) {
    parts.push(`Also ${a.ref}.`);
    if (a.variants?.length) parts.push(`Variants: ${a.variants.map((v) => `${v.ref} (${v.look})`).join("; ")}.`);
    if (a.usage) parts.push(`Use: ${a.usage}`);
  }
  return parts.join(" ");
}

/** The sections whose tags appear in some text (a request or a screen's spec), best matches first. */
export function sectionsFor(text: string, max = 6): LibrarySection[] {
  const t = text.toLowerCase();
  return LIBRARY_SECTIONS.map((s) => ({ s, n: s.tags.filter((tag) => t.includes(tag)).length }))
    .filter((x) => x.n > 0)
    .sort((a, b) => b.n - a.n)
    .slice(0, max)
    .map((x) => x.s);
}

